mapper.select:
SELECT account_id, user_handle, version
FROM auth_passkey_account
WHERE TRUE
AND account_id = #{accountId}
AND user_handle = #{userHandle}

mapper.update:
UPDATE auth_passkey_account account
SET version = version + 1
WHERE account_id = #{accountId}
  AND version = #{expectedVersion}
  AND (
      SELECT COUNT(*)
      FROM auth_passkey_credential credential
      WHERE credential.account_id = account.account_id
        AND credential.status = 'ACTIVE'
        AND credential.deleted = 0
  ) < #{maximumCredentials}

mapper.select:
SELECT 
FROM auth_passkey_credential credential
INNER JOIN auth_passkey_account account ON account.account_id = credential.account_id
WHERE credential.status = 'ACTIVE' AND credential.deleted = 0
AND credential.account_id = #{accountId}
AND credential.credential_id = #{credentialId}
AND account.user_handle = #{userHandle}
ORDER BY credential.created_at, credential.id

mapper.delete:
WITH removed_credentials AS (
    DELETE FROM auth_passkey_credential
    WHERE account_id = #{accountId}
    RETURNING id
)
DELETE FROM auth_passkey_account
WHERE account_id = #{accountId}
